// The files a new app starts from, generated by the same canonical starter the
// CLI (`fas init`) and the VibeCode builder use, so MCP-created apps track
// releases/starter.json instead of the template mirror repositories, which the
// hourly sync cannot update when the workflow changes (#451, #523).

import { getTemplateFiles, substituteAppName } from "../../../packages/cli/src/lib/starter-foundation";
import { type RepoFile, textToB64 } from "./github.js";

export type AppKind = "standalone" | "connected";

/** The scaffold as repo files (path → base64 text), with every identity token resolved. */
export function buildScaffold(appId: string, kind: AppKind): Map<string, RepoFile> {
  const generated = getTemplateFiles({ store: "apps", nounPlural: "apps", r2Bucket: "fas-apps" }, "generic", kind);
  const files = new Map<string, RepoFile>();
  for (const [path, text] of Object.entries(substituteAppName(generated, appId, appId))) {
    files.set(path, { content: textToB64(text), encoding: "base64" });
  }
  return files;
}
